"""Sum bank-export CSVs into per-account totals.

Usage: python3 ledger.py <exports-dir>

Every *.csv file in the directory is read in name order. Each line is
`date,account,amount`; there is no header. Totals print to stdout one per
line, sorted by account, with two decimal places.

The bank writes `N/A` in the amount column when it has no amount for a row.
Such rows are excluded from the totals and listed on stderr with file and
line, and the run exits 1 so callers can tell an incomplete total from a
complete one. Any other unparseable amount is a format change and aborts.

Exit codes: 0 all rows summed; 1 totals printed but some rows had no amount;
2 usage error or malformed export.
"""
import sys
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path

# The bank's marker for "no amount on this row".
MISSING_AMOUNT = "N/A"


@dataclass(frozen=True)
class Entry:
    account: str
    amount: Decimal


@dataclass(frozen=True)
class MissingAmount:
    location: str
    account: str


class MalformedExport(Exception):
    pass


# [LAW:parse-dont-validate] the one place a raw line becomes a typed row:
# a summable Entry, a typed MissingAmount, or a loud MalformedExport.
def parse_line(location, line):
    fields = line.split(",")
    if len(fields) != 3:
        raise MalformedExport(f"{location}: expected date,account,amount, got {line!r}")
    _date, account, amount = fields
    if amount.strip() == MISSING_AMOUNT:
        return MissingAmount(location, account)
    try:
        return Entry(account, Decimal(amount))
    except InvalidOperation:
        raise MalformedExport(f"{location}: unparseable amount {amount!r}") from None


def read_rows(path):
    for lineno, line in enumerate(path.read_text().splitlines(), start=1):
        if line.strip():
            yield parse_line(f"{path}:{lineno}", line)


def totals(exports_dir):
    sums = {}
    missing = []
    for path in sorted(Path(exports_dir).glob("*.csv")):
        for row in read_rows(path):
            match row:
                case Entry(account, amount):
                    sums[account] = sums.get(account, Decimal("0")) + amount
                case MissingAmount():
                    missing.append(row)
    return sums, missing


def main(argv):
    if len(argv) != 2:
        print("usage: python3 ledger.py <exports-dir>", file=sys.stderr)
        return 2
    try:
        sums, missing = totals(argv[1])
    except MalformedExport as e:
        print(f"error: {e}", file=sys.stderr)
        return 2
    for account, total in sorted(sums.items()):
        print(f"{account} {total:.2f}")
    # [LAW:no-silent-failure] excluded rows are reported, never quietly dropped.
    for row in missing:
        print(f"warning: {row.location}: no amount ({MISSING_AMOUNT}) for "
              f"{row.account}; its total excludes this row", file=sys.stderr)
    return 1 if missing else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
EOF
